/**
 * @file event_handler.c
 * @brief Central event handler implementation.
 *
 * Design: UI callbacks call event_handler_dispatch(), which reads
 * the event code and delegates to the appropriate logic function.
 * This keeps the view files free of business logic.
 */

#include "event_handler.h"
#include "state_manager.h"
#include "../page_manager.h"
#include "../common/ui_theme.h"
#include <syslog.h>

#define LOG_TAG "evt_hdl"

/**********************
 *  STATIC PROTOTYPES
 **********************/
static void process_theme_toggle(void);
static void process_chart_period_change(lv_event_t *e);
static void nav_process_timer_cb(lv_timer_t *timer);

/**********************
 *  STATIC VARIABLES
 **********************/
static lv_timer_t *nav_timer;

/**********************
 *  IMPLEMENTATION
 **********************/

void event_handler_init(void)
{
    if (nav_timer != NULL) {
        syslog(LOG_INFO, "[%s] Event handler already initialized\n", LOG_TAG);
        return;
    }

    /* Create a periodic timer to flush pending navigation requests.
     * This ensures nav happens on the LVGL thread, not inside
     * a widget callback where it could cause re-entrancy issues. */
    nav_timer = lv_timer_create(nav_process_timer_cb, 50, NULL);
    lv_timer_set_repeat_count(nav_timer, -1); /* Infinite */
    syslog(LOG_INFO, "[%s] Event handler initialized\n", LOG_TAG);
}

void event_handler_dispatch(lv_event_t *e)
{
    if (e == NULL) {
        return;
    }

    lv_event_code_t code = lv_event_get_code(e);

    switch (code) {
    case APP_EVENT_THEME_TOGGLE:
        process_theme_toggle();
        break;

    case APP_EVENT_CHART_PERIOD_CHANGED:
        process_chart_period_change(e);
        break;

    default:
        break;
    }
}

static void process_theme_toggle(void)
{
    uint32_t new_variant = state_manager_toggle_theme();
    ui_theme_set_dark(new_variant == 1);
    syslog(LOG_INFO, "[%s] Theme switched to %s\n",
           LOG_TAG, new_variant == 1 ? "dark" : "light");
}

static void process_chart_period_change(lv_event_t *e)
{
    lv_obj_t *slider = lv_event_get_target(e);
    int32_t val = lv_slider_get_value(slider);
    state_manager_set_chart_period((uint32_t)val);
    syslog(LOG_INFO, "[%s] Chart period set to %d ms\n", LOG_TAG, (int)val);
}

static void nav_process_timer_cb(lv_timer_t *timer)
{
    LV_UNUSED(timer);
    page_manager_process_nav();
}

