/**
 * @file view_settings.c
 * @brief Settings screen implementation.
 *
 * Layout:
 *  - Header with back button
 *  - Theme toggle card (light/dark switch)
 *  - Chart refresh rate slider
 *  - About / info card
 *
 * All state changes go through state_manager / ui_theme APIs.
 * Views do NOT contain business logic; they only create widgets
 * and forward user interactions.
 */

#include "view_settings.h"
#include "../app_context.h"
#include "../common/ui_theme.h"
#include "../common/ui_components.h"
#include "../logic/state_manager.h"
#include "../page_manager.h"

#include <inttypes.h>

/**********************
 *  CALLBACKS
 **********************/

static void update_period_label(lv_obj_t *label, uint32_t period_ms)
{
    if (label != NULL) {
        lv_label_set_text_fmt(label, "%"PRIu32" ms", period_ms);
    }
}

/**
 * Switch toggle -> toggle theme via state manager + ui_theme.
 * This is a thin view callback that delegates to the proper modules.
 */
static void theme_switch_cb(lv_event_t *e)
{
    uint32_t new_variant = state_manager_toggle_theme();
    ui_theme_set_dark(new_variant == 1);
}

/**
 * Slider value changed -> update chart period in state manager.
 */
static void period_slider_cb(lv_event_t *e)
{
    lv_obj_t *slider = lv_event_get_target(e);
    lv_obj_t *value_label = lv_event_get_user_data(e);
    int32_t val = lv_slider_get_value(slider);

    state_manager_set_chart_period((uint32_t)val);
    update_period_label(value_label, (uint32_t)val);
}

/**********************
 *  PAGE LIFECYCLE
 **********************/

static lv_obj_t *settings_create(lv_obj_t *parent)
{
    app_context_t *ctx = app_ctx_get();

    /* Main container */
    lv_obj_t *container = lv_obj_create(parent);
    lv_obj_set_size(container, LV_PCT(100), LV_PCT(100));
    lv_obj_set_flex_flow(container, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_all(container, 0, 0);
    lv_obj_set_style_pad_gap(container, 0, 0);
    lv_obj_set_style_bg_color(container,
                              ui_theme_get_color(THEME_COLOR_BG), 0);
    lv_obj_set_style_bg_opa(container, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(container, 0, 0);

    /* Header */
    ui_comp_create_header(container, "系统设置", true);

    /* Content area */
    lv_obj_t *content = lv_obj_create(container);
    lv_obj_set_size(content, LV_PCT(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(content, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_all(content, 16, 0);
    lv_obj_set_style_pad_gap(content, 16, 0);
    lv_obj_set_style_bg_opa(content, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(content, 0, 0);
    lv_obj_set_flex_grow(content, 1);

    /* ---- Theme Card ---- */
    lv_obj_t *theme_card = ui_comp_create_card(content);

    lv_obj_t *theme_title = lv_label_create(theme_card);
    lv_label_set_text(theme_title, LV_SYMBOL_EYE_OPEN "  外观");
    ui_theme_apply_title_style(theme_title);

    ui_comp_create_separator(theme_card);

    /* Dark mode switch row */
    lv_obj_t *switch_row = lv_obj_create(theme_card);
    lv_obj_set_size(switch_row, LV_PCT(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(switch_row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(switch_row, LV_FLEX_ALIGN_SPACE_BETWEEN,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_bg_opa(switch_row, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(switch_row, 0, 0);
    lv_obj_set_style_pad_all(switch_row, 0, 0);
    lv_obj_remove_flag(switch_row, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *dark_label = lv_label_create(switch_row);
    lv_label_set_text(dark_label, "深色模式");
    ui_theme_apply_text_style(dark_label);

    lv_obj_t *theme_sw = lv_switch_create(switch_row);
    if (ctx->state.theme_variant == 1) {
        lv_obj_add_state(theme_sw, LV_STATE_CHECKED);
    }
    /* Listen for LV_EVENT_VALUE_CHANGED (the native switch event) */
    lv_obj_add_event_cb(theme_sw, theme_switch_cb,
                        LV_EVENT_VALUE_CHANGED, NULL);

    /* ---- Chart Settings Card ---- */
    lv_obj_t *chart_card = ui_comp_create_card(content);

    lv_obj_t *chart_title = lv_label_create(chart_card);
    lv_label_set_text(chart_title, LV_SYMBOL_CHARGE "  数据刷新");
    ui_theme_apply_title_style(chart_title);

    ui_comp_create_separator(chart_card);

    /* Refresh rate slider */
    lv_obj_t *rate_label = lv_label_create(chart_card);
    lv_label_set_text(rate_label, "刷新周期 (ms)");
    ui_theme_apply_text_style(rate_label);

    lv_obj_t *slider = lv_slider_create(chart_card);
    lv_obj_t *period_value;
    uint32_t period_ms = state_manager_get_chart_period();

    lv_slider_set_range(slider, 100, 2000);
    lv_slider_set_value(slider, (int32_t)period_ms, LV_ANIM_OFF);
    lv_obj_set_width(slider, LV_PCT(100));
    lv_obj_set_style_bg_color(slider,
        ui_theme_get_color(THEME_COLOR_PRIMARY), LV_PART_INDICATOR);

    /* Period value display */
    period_value = ui_comp_create_labeled_value(chart_card, "当前间隔", "");
    update_period_label(period_value, period_ms);

    /* Listen for LV_EVENT_VALUE_CHANGED (the native slider event) */
    lv_obj_add_event_cb(slider, period_slider_cb,
                        LV_EVENT_VALUE_CHANGED, period_value);

    /* ---- About Card ---- */
    lv_obj_t *about_card = ui_comp_create_card(content);

    lv_obj_t *about_title = lv_label_create(about_card);
    lv_label_set_text(about_title, LV_SYMBOL_INFO "  关于");
    ui_theme_apply_title_style(about_title);

    ui_comp_create_separator(about_card);

    ui_comp_create_labeled_value(about_card, "应用",
                                 "心帆智创面板");
    ui_comp_create_labeled_value(about_card, "平台",
                                 "D13x / OpenVela");
    ui_comp_create_labeled_value(about_card, "LVGL 色深",
                                 "24 bit");
    ui_comp_create_labeled_value(about_card, "中文字体",
                                 "App CJK 16");

    /* Back to home button at bottom */
    static const char *btn_labels[] = { "返回首页" };
    static const app_page_id_t btn_targets[] = { PAGE_HOME };
    ui_comp_create_nav_buttons(content, btn_labels, btn_targets, 1);

    return container;
}

static void settings_on_enter(void)
{
    /* Could refresh dynamic values here */
}

/**********************
 *  PUBLIC API
 **********************/

static const app_page_cbs_t settings_cbs = {
    .create   = settings_create,
    .on_enter = settings_on_enter,
    .on_exit  = NULL,
    .destroy  = NULL,
};

const app_page_cbs_t *view_settings_get_cbs(void)
{
    return &settings_cbs;
}

